SourceCode.Declaration:
/// <summary>
/// Cancel sales order lines batch job
/// CB129 Open PO cancellation
/// </summary>
internal final class METPurchCancelController extends SysOperationServiceController implements BatchRetryable
{
}

Method.Source:
/// <summary>Constuct new object</summary>
/// <param name = "_args">Arguments</param>
/// <param name = "_executionMode">Execution mode</param>
/// <returns>New Controller Object</returns>
public static METPurchCancelController construct(Args _args, SysOperationExecutionMode _executionMode = SysOperationExecutionMode::Synchronous)
{
    METPurchCancelController controller = new METPurchCancelController();
    controller.parmExecutionMode(_executionMode);
    controller.parmArgs(_args);

    return controller;
}

/// <summary>
/// New method specifying the service class method to call
/// </summary>
protected void new()
{
    super(classstr(METPurchCancelService), methodstr(METPurchCancelService, processOperation), SysOperationExecutionMode::Synchronous);
}

/// <summary>
/// The caption method of the batch job dialog.
/// </summary>
/// <returns>String value to be used on dialog</returns>
public ClassDescription caption()
{
    return "@MET:CancelPOlines";
}

/// <summary>
/// The main method of the batch job.
/// </summary>
/// <param name = "_args">The arguments passed by the caller object.</param>
public static void main(Args _args)
{
    FormRun                 caller;
    MultiSelectionHelper    helper;
    PurchLine               purchLine;
    SysOperationController  controller = METPurchCancelController::construct(_args);
    container               conPurchLine;
    METPurchCancelContract  contract;

    boolean confirmCancel = Box::okCancel("@MET:CancelWarning",DialogButton::Cancel);

    if (confirmCancel)
    {
        caller    = _args.caller();
        helper    = MultiSelectionHelper::createFromCaller(caller);
        purchLine = helper.getFirst();

        while (purchLine)
        {
            conPurchLine += purchLine.RecId;
            purchLine = helper.getNext();
        }

        contract = controller.getDataContractObject() as METPurchCancelContract;
        contract.parmPurchLineRecords(conPurchLine);

        controller.startOperation();
    }
}

/// <summary>
/// Specifies if the batch task is retryable for transient exceptions or not.
/// </summary>
/// <returns>
/// If true is returned, the batch task is retryable, otherwise it is not.
/// </returns>
[Hookable(false)]
final boolean isRetryable()
{
    return true;
}
